import{c as t,Q as r,j as a,m as o}from"./chunks/framework.BPKcPtvA.js";const l=JSON.parse('{"title":"About our Themes","description":"","frontmatter":{},"headers":[],"relativePath":"general/about-our-themes.md","filePath":"general/about-our-themes.md"}'),s={name:"general/about-our-themes.md"};function n(h,e,i,c,m,u){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="about-our-themes" tabindex="-1">About our Themes <a class="header-anchor" href="#about-our-themes" aria-label="Permalink to &quot;About our Themes&quot;">​</a></h1><p>Each of our themes is carefully coded respecting the <a href="https://codex.wordpress.org/WordPress_Coding_Standards" target="_blank" rel="noreferrer">WordPress coding standards</a>. Our themes are sold directly on <a href="https://wolfthemes.com" target="_blank" rel="noreferrer">wolfthemes.com</a> and on ThemeForest, where they have been reviewed by the ThemeForest review team, to guarantee the highest quality.</p><p>Our most recent themes share the same code structure and core features to maintain consistency among the theme collection and allow switching from theme to theme easily. What makes each theme unique is the specific features and design it offers depending on the field it targets.</p><p>For example, a theme dedicated to musicians will offer a discography feature and a theme for designers will come with a portfolio feature. In addition to this knowledge base, each theme comes with a theme documentation that covers theme specific features.</p><p>If you&#39;re stuck with anything, be sure to search this knowledge base and the theme documentation before reaching us for further help. Most issues you may encounter or questions you may ask are covered in the articles. If you can&#39;t find a solution here, feel free to <a href="https://wolfthemes.ticksy.com" target="_blank" rel="noreferrer">post a ticket</a>.</p>',5)])])}const f=t(s,[["render",n]]);export{l as __pageData,f as default};
